import React, { useEffect, useRef, useState } from 'react';
import Background from '../../../components/shared/Ui/Background';
import animationData from '../../../../static/Images/WhyParentsLoveUs/data-comp-v1.json';
import profileImg from '../../../../static/Images/reviews/image.svg';
import stars from '../../../../static/Images/reviews/stars.svg';
import scribble from '../../../../static/Images/reviews/scribble.svg';
import bigstar from '../../../../static/Images/reviews/star.svg';

import "../../../Styles/pages/reviews.css";
import "../../../Styles/pages/realfeedback.css";
import avatar from "../../../../static/Images/reviews/bitmap.svg";



const reviews = [
  {
    name: "Janette Williams",
    comment: "Best back-to-school shopping experience! The box arrived on time, everything was organized, and it perfectly matched my child’s school supply list. Highly recommend this service!",
    img: avatar,
  },
  {
    name: "Carlos Mendez",
    comment: "I didn’t have to set foot in a store. Everything showed up exactly as described and my daughter loved unpacking it all. Will use again next year!",
    img: avatar,
  },
  {
    name: "Emily Nguyen",
    comment: "This saved me HOURS. The supplies were correct, the brands were good quality, and the packaging was neat and kid-friendly.",
    img: avatar,
  },
  {
    name: "Sarah Thompson",
    comment: "No more guessing or last-minute shopping. Everything we needed was there, and my son was so excited to open the box!",
    img: avatar,
  },
  {
    name: "Marcus Lee",
    comment: "I used to dread school supply shopping. This made it actually enjoyable. One click and done!",
    img: profileImg,
  },
];

const RealFeedback = () => {
  const contentRef = useRef(null);
  const [contentHeight, setContentHeight] = useState('100vh');
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const node = contentRef.current;
    if (!node) return;

    const updateHeight = () => {
      const height = node.getBoundingClientRect().height;
      setContentHeight(`${height + 500}px`);
    };

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(node);
    const timer = setTimeout(updateHeight, 500);

    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, [contentRef]);

  // Carousel loop effect
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrent((prev) => (prev + 1) % reviews.length);
    }, 5000); // 5 seconds
    return () => clearInterval(interval);
  }, []);

  const review = reviews[current];

  return (
    <section className='real-feedback-container'>
     

      <main className='feedback-main' style={{ backgroundColor : '#FEAE37'}}>
         <img src={bigstar} alt="Big star" className="bigstar-feedback" />
        <div className="feedback-content">
          <span invertedDescription="true" className='section-subtitle' style={{ color : 'black'}}>What Parents Are Saying</span>
          <h1 invertedText="true" className='section-title'>Real Feedback, Real Results!</h1>
          <p invertedText="true" className="section-description">
            Our customers love the convenience, quality, and peace of mind we provide. From the ease of ordering to the excitement of receiving perfectly packed boxes, see why parents trust us to get their kids ready for school—stress-free.
          </p>
        </div>

        {/* ✅ Carousel */}
        <div className="review-carousel-wrapper" ref={contentRef}>
          <div className="review-container review-carousel-slide" key={current}>
            <div className='review-content-image'>
              <img src={review.img} alt={`Profile of ${review.name}`} className='review-content-img' />
            </div>
            <div className='review-content-text'>
              <div className='review-content'>
                <span className="review-count-real-feedback">5.0</span>
                <div>
                  <img src={stars} alt="5 star rating" />
                </div>
              </div>
            </div>
            <div className='review-content-scribble'>
              <h5 className='review-user-name'>{review.name}</h5>
              <p className="review-user-comment">{review.comment}</p>
              <img src={scribble} alt="review scribble" className='scribble-image-review' />
            </div>
          </div>
        </div>
      </main>
    </section>
  );
};

export default RealFeedback;
