import React, { useRef, useEffect, useState } from 'react';
import { useInView } from 'react-intersection-observer'; // ⬅️ Import here
import "../../../Styles/pages/whyParentsLoveUs.css";
import Background from '../../../components/shared/Ui/Background';
import animationData from '../../../../static/Images/WhyParentsLoveUs/data-comp-v1.json';
import bottom_cloud from "../../../../static/Images/header/cloud-bottom.svg";
import nomoretrips from "../../../../static/Images/WhyParentsLoveUs/no-trips.svg";
import heavybagsgone from "../../../../static/Images/WhyParentsLoveUs/bags.svg";
import calmbeforeschool from "../../../../static/Images/WhyParentsLoveUs/calm.svg";
import nowrongitems from "../../../../static/Images/WhyParentsLoveUs/no-wrong.svg";
import oneclickdone from "../../../../static/Images/WhyParentsLoveUs/one-click.svg";
import skipthechaos from "../../../../static/Images/WhyParentsLoveUs/chaos.svg";
import suppliesBooksJson from '../../../../static/lottie-magic-school-bus-books.json';
import { GLOBAL_DEBUG } from '../../../admin/debug';

 const DEBUG = GLOBAL_DEBUG

const BasicLottie = React.lazy(() => import('../BasicLottie/BasicLottie'));

function WhyParentsLoveUs() {
  const contentRef = useRef(null);
  const [contentHeight, setContentHeight] = useState('100vh');

 const [hasPlayed, setHasPlayed] = useState(false);

const { ref: lottieRef, inView } = useInView({
  threshold: 0.3,
  triggerOnce: false, // still false so we can manually track
  rootMargin: '-20% 0px 0px 0px', 
});

useEffect(() => {
  if (inView && !hasPlayed) {
    setHasPlayed(true);
  }
}, [inView, hasPlayed]);

  useEffect(() => {
    const node = contentRef.current;
    if (!node) return;

    const updateHeight = () => {
      const height = node.getBoundingClientRect().height;
      setContentHeight(`${height + 200}px`);
    };

    const observer = new ResizeObserver(() => updateHeight());
    observer.observe(node);
    const timer = setTimeout(updateHeight, 500);

    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, [contentRef]);

 const f = ( x ) => x.replaceAll(' ','&nbsp;').replaceAll('-','&#8209;');


 const whyParentsLoveUsData = [
  {
    id: 1,
    title: f("No More Trips"),
    subtitle: <>Skip store runs, gas, and parking. Everything arrives at your door — no need to leave the house.</>,
    image: nomoretrips,
    height: 250
   
  },
  {
    id: 2,
    title: f("Heavy Bags Gone"),
    subtitle: <>No more carrying overloaded bags from store to car to house. Everything’s shipped, packed, and ready.</>,
    image: heavybagsgone,
    height : 200
   
  },
  {
    id: 3,
    title: f("No Wrong Items"),
    subtitle: <>Every supply matches your school's list exactly — no guesswork, returns, or teacher complaints</>,
    image: nowrongitems,
    height : 180
  
  },
  {
    id: 4,
    title: f(" Skip The Chaos"),
    subtitle: <>Avoid crowds, tantrums, and checkout lines. Back-to-school shopping doesn’t have to be a nightmare</>,
    image: skipthechaos,
    height : 200
  
  },
    {
    id: 5,
    title: f("One Click Done"),
    subtitle: "Stop wasting hours shopping around. Order everything in one fast, simple checkout.",
    image: oneclickdone,
    height : 200,

  },
  {
    id: 6,
    title: f("Calm Before School"),
    subtitle: <>Everything’s ready ahead of time — no rushing, no stress. Just peace, laughter, and quality time with the ones you love.</>,
    image: calmbeforeschool,
    height : 250
  
  },

];

  return (
    <div className=' whyparentsloveus-container'>
      <div className='whyparentsloveus-bottom-cloud'>
        <img src={bottom_cloud} alt="" />
      </div>
    

      {/* ✅ Attach ref to Lottie container */}
      <div className='whyparentsloveus-books-image' ref={lottieRef} style={{ position: 'absolute', marginTop : -20 }}>
      <React.Suspense fallback={<div>Loading animation...</div>}>
        <BasicLottie 
          noloop={true}
          animationData={suppliesBooksJson} 
          height={700} 
          shouldPlay={hasPlayed} // ✅ now only true on first scroll into view
        />
      </React.Suspense>
      </div>

      <Background 
        bg="#0B3A4C" 
        height={contentHeight} 
        source={animationData} 
      /> 

      <section className='whyparentsloveus-content-section container'>
        <main className='whyparentsloveus-content-main' ref={contentRef}>
          <div className='whyparentsloveus-content-main-container' >
            <span className='section-subtitle'>Why Parents Love It</span>
            <h1 className='section-title' invertedtext="true">Smarter Shopping</h1>
            <p className="section-description">
              Save time, skip the crowds, and feel confident knowing your child has exactly what they need. 
              From pre-approved school lists to doorstep delivery and one-click reorders, our simple system 
              makes back-to-school shopping fast, stress-free, and completely foolproof.
            </p>
          </div>
          
          <div className='whyparentsloveus-items-container-container' style={{ 
            
            border : DEBUG  && '1px solid red', 
            
            verticalAlign : 'top' }}>
            {whyParentsLoveUsData.map((item) => (
              <div className='whyparentsloveus-items-main-container' key={item.id}  style={{ 
                
                border : DEBUG  &&  '', 
                verticalAlign : 'top' }}>
                
                <div className='whyparentsloveus-item-image-replacement' style={{ 
                  
                  border : DEBUG  && '1px solid purple', 
                  
                  verticalAlign : 'top' }}>
                  <img src={item.image} alt={item.title} height={item.height} width={item.width} /> 
                
                </div>
                <div>
                 <h1
  className='whyparentsloveus-item-title'
  dangerouslySetInnerHTML={{ __html: item.title }}
style={{ 
  
  border : DEBUG && '1px solid red'
  
  , verticalAlign : 'top' }}></h1>

                  <p style={{ 
                    
                    border : DEBUG && '1px solid red', 
                    
                    verticalAlign : 'top' }}className='whyparentsloveus-item-subtitle'>{item.subtitle}</p>
                </div>
              </div>
            ))}
          </div>
        </main>
      </section>
    </div>
  );
}

export default WhyParentsLoveUs;
